export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds,
  generatedAt = new Date().toISOString()
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholds) {
    const validation = evaluateThresholds(thresholds, evaluations);
    report.passed = validation.passed;
    report.thresholds = validation.thresholds;
  }

  return report;
}

