    // Call validateThresholds from frai-core
    // This checks:
    // - All metrics in thresholds exist in evaluations
    // - (Format and range already checked above)
    const validationErrors = (Eval.validateThresholds as unknown as (thresholds: unknown, evaluations: unknown) => string[])
      (thresholds, evaluations);
